/*
 * swio: the single-wire debug interface to the target, on TSWIO (Zwölf
 * pin 10), generated by TIM2 and DMA so that the USB interrupt is never
 * blocked. See docs/swio.md.
 */

#ifndef SWIO_H
#define SWIO_H

#include <stdint.h>
#include "wkproto.h"
#include "swio_bits.h"

/* the timing in use (WK_TM_* layout); swio_set_timing checks it */
extern uint8_t swio_tm[WK_TM_LEN];
int swio_set_timing(const uint8_t *tm);     /* 0, or -1 if invalid */

/* packets sent, and those that came back incomplete (PROFILE) */
extern uint32_t swio_packets, swio_bad;

/* the captures of the last packet */
extern uint8_t swio_cap[48];
extern uint8_t swio_ncap;

void swio_on(void);         /* only with target power on */
void swio_off(void);        /* pins back to floating inputs */
int swio_is_on(void);

/* 0, or -1 if the packet came back incomplete */
int swio_write(uint8_t reg, uint32_t val);
int swio_read(uint8_t reg, uint32_t *val);

/* the link test (WK_CMD_SWIO_TEST): fills a WK_LT_LEN reply */
void swio_link_test(uint32_t n, uint8_t *out);

#endif
